B.aSZ=new A.iJ('Bu kullan\u0131m ko\u015fullar\u0131, Koala by evlumba uygulamas\u0131n\u0131 ("Uygulama") kullan\u0131m\u0131n\u0131z\u0131 d\xfczenler. Uygulamay\u0131 kullanarak bu ko\u015fullar\u0131 kabul etmi\u015f say\u0131l\u0131rs\u0131n\u0131z.',null)
B.aT1=new A.iJ("Son g\xfcncelleme: 18 Mart 2026",null)
B.aUj=new A.j7("Hizmet Tan\u0131m\u0131",null)
B.aSV=new A.iJ("Koala, yapay zeka destekli bir mekan analiz uygulamas\u0131d\u0131r. Kullan\u0131c\u0131lar soru foto\u011fraf\u0131 \xe7ekerek ad\u0131m ad\u0131m \xe7\xf6z\xfcm alabilir. Uygulama 9 farkl\u0131 bran\u015fta AI destekli \xf6\u011fretim hizmeti sunar.",null)
B.aUf=new A.j7("Hesap ve Kay\u0131t",null)
B.aQp=new A.eF("Uygulamay\u0131 kullanmak i\xe7in Google veya telefon numaras\u0131 ile hesap olu\u015fturman\u0131z gerekir",null)
B.aQs=new A.eF("Hesap bilgilerinizin do\u011fru ve g\xfcncel olmas\u0131ndan siz sorumlusunuz",null)
B.aQb=new A.eF("Hesab\u0131n\u0131z\u0131n g\xfcvenli\u011finden siz sorumlusunuz",null)
B.aUo=new A.j7("Kredi Sistemi",null)
B.aQ9=new A.eF("Her yeni kullan\u0131c\u0131ya 10 \xfccretsiz kredi verilir",null)
B.aQy=new A.eF("Her mekan analizi 1 kredi harcar",null)
B.aQx=new A.eF("Ek kredi uygulama i\xe7i sat\u0131n alma ile edinilebilir",null)
B.aQw=new A.eF("Sat\u0131n al\u0131nan krediler iade edilemez",null)
B.aUg=new A.j7("Kabul Edilebilir Kullan\u0131m",null)
B.aSS=new A.iJ("Uygulamay\u0131 yaln\u0131zca ki\u015fisel mekan analizi ama\xe7l\u0131 kullanabilirsiniz. A\u015fa\u011f\u0131daki davran\u0131\u015flar yasakt\u0131r:",null)
B.aQv=new A.eF("Uygulamay\u0131 k\xf6t\xfcye kullanmak veya ba\u015fkalar\u0131n\u0131n kullan\u0131m\u0131n\u0131 engellemek",null)
B.aQo=new A.eF("Otomatik botlar veya scraper kullanmak",null)
B.aQr=new A.eF("Uygulamay\u0131 s\u0131nav s\u0131ras\u0131nda kopya \xe7ekmek i\xe7in kullanmak",null)
